import numpy as np
import pandas as pd
import random

def task_func(rows=3, cols=2, min_val=0, max_val=100, seed=0):
    random.seed(seed)
    if rows <= 0 or cols <= 0:
        return pd.DataFrame()
    matrix = [[random.randint(min_val, max_val) for _ in range(cols)] for _ in range(rows)]
    return pd.DataFrame(matrix)
